<?php
require_once __DIR__.'/config/constants.php';$u=require_login();if(!is_post())redirect('wishlist.php');verify_csrf();$id=filter_input(INPUT_POST,'food_id',FILTER_VALIDATE_INT);if(!$id)redirect('foods.php');$s=db()->prepare('SELECT id FROM tbl_wishlist WHERE user_id=? AND food_id=?');$s->execute([$u['id'],$id]);if($s->fetchColumn()){$s=db()->prepare('DELETE FROM tbl_wishlist WHERE user_id=? AND food_id=?');$s->execute([$u['id'],$id]);flash('info','Removed from wishlist.');}else{$s=db()->prepare("INSERT INTO tbl_wishlist(user_id,food_id,created_at) SELECT ?,id,NOW() FROM tbl_food WHERE id=? AND active='Yes'");$s->execute([$u['id'],$id]);flash('success','Saved to your wishlist.');}safe_back('wishlist.php');